/** Mapas indexados para pesquisas rápidas O(1) */
export const NOZZLES_BY_ID: Map<string, Nozzle> = new Map(
  NOZZLES_DATABASE.map(n => [n.id, n])
);

/** Lista ordenada de marcas disponíveis */
export const AVAILABLE_BRANDS: string[] = Array.from(
  new Set(NOZZLES_DATABASE.map(n => n.brand))
).sort();

/** Grupos canónicos de tipos de bico na ordem pedagógica DATERRA Smart */
export const NOZZLE_TYPE_GROUPS = [
  'Bicos cónicos',
  'Bicos de fenda',
  'Bicos de fenda com indução de ar',
  'Bicos de fenda dupla',
  'Bicos de fenda descentrada',
  'Multi-jato / estilete',
  'Outros'
] as const;

export type NozzleTypeGroup = typeof NOZZLE_TYPE_GROUPS[number];

/** Mapeia a designação real de nozzleType para um dos 7 grupos canónicos */
export function getNozzleTypeGroup(nozzleType: string): NozzleTypeGroup {
  const t = (nozzleType || '').toLowerCase();
  if (t.includes('cone')) return 'Bicos cónicos';
  if (t.includes('dupla') || t.includes('twin')) return 'Bicos de fenda dupla';
  if (t.includes('descentrada') || t.includes('extremidade') || t.includes('longo alcance') || t.includes('oci') || t.includes('off-center')) return 'Bicos de fenda descentrada';
  if (t.includes('indução de ar') || t.includes('inducao') || t.includes('ar comprimido') || t.includes('air')) return 'Bicos de fenda com indução de ar';
  if (t.includes('estilete') || t.includes('jato') || t.includes('jatos') || t.includes('fertilizante') || t.includes('stream')) return 'Multi-jato / estilete';
  if (t.includes('fenda') || t.includes('espelho') || t.includes('leque')) return 'Bicos de fenda';
  return 'Outros';
}

export interface GroupedModelItem {
  model: string;
  nozzleType: string;
  group: NozzleTypeGroup;
}

export interface ModelGroup {
  group: NozzleTypeGroup;
  models: GroupedModelItem[];
}

/** Retorna os modelos agrupados por tipo para uma marca (ou de todo o catálogo se marca omitida) */
export function getGroupedModelsForBrand(brand?: string): ModelGroup[] {
  const sourceNozzles = brand
    ? NOZZLES_DATABASE.filter(n => n.brand === brand)
    : NOZZLES_DATABASE;

  if (sourceNozzles.length === 0) return [];

  // Mapear cada modelo único e o seu nozzleType representativo
  const modelMap = new Map<string, { nozzleType: string; group: NozzleTypeGroup }>();
  for (const n of sourceNozzles) {
    if (!modelMap.has(n.model)) {
      const group = getNozzleTypeGroup(n.nozzleType);
      modelMap.set(n.model, { nozzleType: n.nozzleType, group });
    }
  }

  // Agrupar modelos por grupo canónico na ordem obrigatória
  const groups: ModelGroup[] = [];
  for (const groupName of NOZZLE_TYPE_GROUPS) {
    const modelsInGroup: GroupedModelItem[] = [];
    for (const [model, info] of modelMap.entries()) {
      if (info.group === groupName) {
        modelsInGroup.push({
          model,
          nozzleType: info.nozzleType,
          group: info.group
        });
      }
    }
    if (modelsInGroup.length > 0) {
      // Ordenar alfabeticamente os modelos dentro do grupo
      modelsInGroup.sort((a, b) => a.model.localeCompare(b.model, 'pt-PT'));
      groups.push({
        group: groupName,
        models: modelsInGroup
      });
    }
  }

  return groups;
}

/** Retorna os modelos disponíveis para um fabricante */
export function getModelsForBrand(brand: string): string[] {
  if (!brand) return [];
  const models = new Set<string>();
  for (const n of NOZZLES_DATABASE) {
    if (n.brand === brand) {
      models.add(n.model);
    }
  }
  return Array.from(models).sort();
}

/** Retorna todas as variantes de um fabricante e modelo */
export function getVariantsForModel(brand: string, model: string): Nozzle[] {
  if (!brand || !model) return [];
  return NOZZLES_DATABASE.filter(n => n.brand === brand && n.model === model);
}

/** Estatísticas da base de dados */
export const NOZZLE_DB_STATS = {
  totalNozzles: NOZZLES_DATABASE.length,
  totalBrands: AVAILABLE_BRANDS.length,
  brands: AVAILABLE_BRANDS,
  minPressureGlobal: Math.min(...NOZZLES_DATABASE.map(n => n.pressureMinBar)),
  maxPressureGlobal: Math.max(...NOZZLES_DATABASE.map(n => n.pressureMaxBar))
};
